create extension if not exists pgcrypto;
alter table public."Matches" add column if not exists canonical_match_id uuid;
alter table public."Matches" add column if not exists canonical_state_version bigint not null default 0;
create index if not exists matches_canonical_match_id_idx on public."Matches"(canonical_match_id);
create table if not exists public.canonical_matches(canonical_match_id uuid primary key default gen_random_uuid(),identity_key text not null unique,legacy_match_id uuid,team1 text not null,team2 text not null,competition text,scheduled_start timestamptz,venue text,gender text,format text,season text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists canonical_matches_legacy_idx on public.canonical_matches(legacy_match_id);
create table if not exists public.provider_match_mappings(canonical_match_id uuid not null references public.canonical_matches(canonical_match_id) on delete cascade,provider text not null,provider_match_id text not null,provider_url text,last_seen_at timestamptz,last_event_at timestamptz,raw_identity jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(provider,provider_match_id));
create table if not exists public.match_events(event_id text primary key,canonical_match_id uuid not null references public.canonical_matches(canonical_match_id) on delete cascade,source text not null,source_event_id text,innings integer,over_no integer,ball_no integer,event_type text not null,runs integer,wicket boolean not null default false,occurred_at timestamptz,received_at timestamptz not null default now(),state text not null default 'PROVISIONAL',payload jsonb,created_at timestamptz not null default now());
create index if not exists match_events_order_idx on public.match_events(canonical_match_id,innings,over_no,ball_no,occurred_at,received_at);
create table if not exists public.match_state(canonical_match_id uuid primary key references public.canonical_matches(canonical_match_id) on delete cascade,state_version bigint not null default 0,status text not null default 'UNKNOWN',status_reason text,score jsonb not null default '{}'::jsonb,innings integer not null default 1,batting_team text,stream_status text not null default 'UNKNOWN',confidence numeric(5,4) not null default 0,anomaly_score numeric(5,4) not null default 0,provisional boolean not null default true,last_event_id text,updated_at timestamptz not null default now(),stale boolean not null default false,last_successful_update timestamptz);
create table if not exists public.source_health(source text primary key,weight numeric(5,4) not null default .5,successes bigint not null default 0,failures bigint not null default 0,duplicates bigint not null default 0,invalid_events bigint not null default 0,latency_ms numeric,breaker_state text not null default 'NORMAL',last_seen_at timestamptz,last_event_at timestamptz,updated_at timestamptz not null default now());
create table if not exists public.match_snapshots(id bigint generated by default as identity primary key,canonical_match_id uuid not null references public.canonical_matches(canonical_match_id) on delete cascade,state_version bigint not null,snapshot jsonb not null,created_at timestamptz not null default now(),unique(canonical_match_id,state_version));
create table if not exists public.match_corrections(id bigint generated by default as identity primary key,canonical_match_id uuid not null references public.canonical_matches(canonical_match_id) on delete cascade,correction_event_id text not null unique,actor_type text not null default 'system',previous_state jsonb,corrected_state jsonb,reason text,created_at timestamptz not null default now());
alter table public.streams add column if not exists canonical_match_id uuid;
create index if not exists streams_canonical_match_id_idx on public.streams(canonical_match_id);
update public."Matches" m set canonical_match_id=c.canonical_match_id from public.canonical_matches c where m.canonical_match_id is null and c.legacy_match_id=m.id;
update public.streams s set canonical_match_id=m.canonical_match_id from public."Matches" m where s.canonical_match_id is null and s.match_id=m.id and m.canonical_match_id is not null;
create or replace function public.sync_stream_canonical_match() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if new.canonical_match_id is null then select canonical_match_id into new.canonical_match_id from public."Matches" where id=new.match_id; end if; return new; end; $$;
drop trigger if exists streams_sync_canonical_match on public.streams;
create trigger streams_sync_canonical_match before insert or update of match_id,canonical_match_id on public.streams for each row execute function public.sync_stream_canonical_match();
alter table public.canonical_matches enable row level security;
alter table public.provider_match_mappings enable row level security;
alter table public.match_events enable row level security;
alter table public.match_state enable row level security;
alter table public.source_health enable row level security;
alter table public.match_snapshots enable row level security;
alter table public.match_corrections enable row level security;
drop policy if exists "Public can view canonical matches" on public.canonical_matches;
create policy "Public can view canonical matches" on public.canonical_matches for select to anon,authenticated using(true);
drop policy if exists "Public can view match state" on public.match_state;
create policy "Public can view match state" on public.match_state for select to anon,authenticated using(true);
drop policy if exists "Public can view provider mappings" on public.provider_match_mappings;
create policy "Public can view provider mappings" on public.provider_match_mappings for select to anon,authenticated using(true);
drop policy if exists "Admins can view source health" on public.source_health;
create policy "Admins can view source health" on public.source_health for select to authenticated using(is_admin());
drop policy if exists "Admins can view match events" on public.match_events;
create policy "Admins can view match events" on public.match_events for select to authenticated using(is_admin());
drop policy if exists "Admins can view snapshots" on public.match_snapshots;
create policy "Admins can view snapshots" on public.match_snapshots for select to authenticated using(is_admin());
drop policy if exists "Admins can view corrections" on public.match_corrections;
create policy "Admins can view corrections" on public.match_corrections for select to authenticated using(is_admin());
insert into public.source_health(source,weight) values('sportscore',.95),('cricbuzz',.99),('backup',.85) on conflict(source) do nothing;
